SPEC.G1=function(p){
  var s=[bg(C.w)].concat(chrome(p),[
    IMG({src:CL+'bunge.svg',x:7.5,y:11.5,w:12,h:4,fit:'contain',gray:true})],
    chip(22,11.8,'Company challenge · fragmented grower data',C.ink,32),
    chip(56,11.8,'Urgent need · one season to launch',C.em7,26),[
    T('Six data sources, one decision screen for the agronomist.',{x:7.5,y:18.5,w:62,h:10,s:3.7,b:true,tight:true,lh:1.12})]);
  var d=[['Challenge','Grower data lived in six systems. Agronomists rebuilt the same picture by hand every week.',0],
         ['Team','Embedded pod of 6: engagement lead, designer, three engineers and one agronomist.',0],
         ['Adaptation','We joined their rituals and their QA gates, and moved AI into sprint 1 instead of phase 2.',0],
         ['Results','',1]];
  d.forEach(function(c,i){var x=7.5+i*21.8,y=31,w=20.2;
    s.push(R({x:x,y:y,w:w,h:.42,fill:c[2]?C.lime:C.ink}));
    s.push(T(c[0].toUpperCase(),{x:x,y:y+1.6,w:w,h:2.2,s:1.1,b:true,c:C.g600,cs:1}));
    if(c[2]){
      s.push(T([{text:'8×',options:{}}],{x:x,y:y+4.4,w:w,h:4,s:3,b:true,tight:true}));
      s.push(T('faster time-to-field',{x:x,y:y+8,w:w,h:2.4,s:1.26,b:true,c:C.g600}));
      s.push(T('3k',{x:x,y:y+11,w:w,h:4,s:3,b:true,tight:true}));
      s.push(T('monthly active users',{x:x,y:y+14.6,w:w,h:2.4,s:1.26,b:true,c:C.g600}));
    } else s.push(T(c[1],{x:x,y:y+4.4,w:w,h:12,s:1.32,lh:1.4}));});
  return s;};

SPEC.G2=function(p){
  var s=[bg(C.sage)].concat(chrome(p),[
    IMG({src:CL+'precision-planting.svg',x:7.5,y:11.5,w:14,h:4,fit:'contain',gray:true})],
    chip(24,11.8,'Urgent need · planting window in 11 weeks',C.ink,31),[
    T('From a spreadsheet ritual to a planting plan the crew trusts.',{x:7.5,y:18.5,w:58,h:10,s:3.7,b:true,tight:true,lh:1.12})]);
  var d=[['Before','6 days','to close a planting plan across 40 fields',C.ink],
         ['After 11 weeks','4 hours','same 40 fields, same two agronomists',C.em7],
         ['Held for','3','consecutive seasons without extra headcount',C.ink]];
  d.forEach(function(c,i){var x=7.5+i*29.5;
    s.push(T(c[0].toUpperCase(),{x:x,y:31,w:26,h:2.2,s:1.15,b:true,c:C.g600,cs:1}));
    s.push(T(c[1],{x:x,y:34,w:26,h:7,s:6.4,b:true,tight:true,c:c[3],lh:.95}));
    s.push(T(c[2],{x:x,y:41.5,w:25,h:6,s:1.4,c:C.g600,lh:1.3}));});
  s.push(T('→',{x:33.5,y:35,w:6,h:5,s:3,b:true,c:C.g300}));
  s.push(rule(7.5,47.5,14));return s;};

/* --- H · fotografía --- */;
